-- UNA-Migration-Min-System-Version: 15.0.0-RC4
-- Grids: Studio's own grids are drawn by AG Grid. Left alone once an admin has set another engine.

UPDATE `sys_objects_grid` SET `engine` = 'ag' WHERE `object` IN ('sys_studio_nav_sets', 'sys_studio_forms', 'sys_studio_forms_displays', 'sys_studio_forms_fields', 'sys_studio_forms_pre_lists', 'sys_studio_forms_pre_values', 'sys_studio_categories', 'sys_studio_labels', 'sys_studio_groups_roles', 'sys_studio_search_forms', 'sys_studio_search_forms_fields', 'sys_studio_search_forms_sortable_fields', 'sys_studio_acl', 'sys_studio_roles', 'sys_studio_agents_agents', 'sys_studio_agents_connectors', 'sys_studio_agents_logs', 'sys_studio_agents_models', 'sys_studio_agents_tools', 'sys_studio_agents_vector_store', 'sys_studio_agents_vector_store_data', 'sys_studio_api_configs', 'sys_studio_api_keys', 'sys_studio_api_origins', 'sys_studio_lang_etemplates', 'sys_studio_strg_files', 'sys_studio_strg_images', 'sys_badges_administration') AND `engine` = '';
